import React, { useEffect, useState } from 'react';
import axios from 'axios';
import RequestCard from './RequestCard';
import styles from './RequestQueue.module.css';

function RequestQueue({ user, showToast }) {
  const [requests, setRequests] = useState([]);

  useEffect(() => {
    axios.get('http://localhost:5000/api/requests')
      .then(res => setRequests(res.data))
      .catch(() => setRequests([]));
  }, []);

  const acceptRequest = async (requestId) => {
    try {
      await axios.post('http://localhost:5000/api/requests/accept', { requestId });
      if (showToast) showToast('Request accepted!');
    } catch {
      if (showToast) showToast('Failed to accept request');
    }
  };

  const notifyStudent = async (requestId) => {
    try {
      await axios.post('http://localhost:5000/api/requests/notify', { requestId });
      if (showToast) showToast('Email sent!');
    } catch {
      if (showToast) showToast('Failed to send email');
    }
  };

  return (
    <div className={styles.container}>
      <div className={styles.title}>Request Queue</div>
      {requests.map(req => (
        <RequestCard key={req._id} req={req} user={user} onAccept={acceptRequest} onNotify={notifyStudent} />
      ))}
    </div>
  );
}

export default RequestQueue;
